; slow.s -- generated by tools/fwtask/gen_blobs.py (phase 11.29): item 11: cmd 1 sets state busy, spins n iterations, sets done; a pass that finds busy stores overlap = 1
; Written from doc/specs/usse_isa.md and the records E475/E476 (pclink, lapc), E480 (wdf with
; nothing outstanding), E512 (stad then ldad), E146/E155 (the event task, pa0 to pa2); it is run
; as an EDM task from the page the kernel maps at heap + 0x20000 (index 0x4000). Rules: r0 to r31
; only, no sa write except state.s, no emit, no lock, every store the same value from every lane.

@entry 0
        mov r1, #0xdeadbeef                 ; @patch res+0
        ldad.bypassl1 r2, [r1,+#1], drc0
        ldad.bypassl1 r3, [r1,+#2], drc0
        wdf drc0
        xor.testtanz.chan0 !c0, p2, r3, #1  ; p2 = not busy
        p2 br @chk
        mov r7, #0x00000001
        stad [r1,+#4], r7                  ; overlap = 1 (a flag)
        idf drc0, bif
        wdf drc0
chk:
        and.testtanz.chan0 !c0, p0, r2, r2
        p0 br @work
tail:
        mov r30, #0xdeadbeef                ; @patch cont0
        mov pclink, r30
        lapc
work:
        xor.testtaz.chan0 !c0, p1, r2, #1
        p1 br @c1
        br @tail
c1:
        ldad.bypassl1 r8, [r1,+#10], drc0   ; n
        wdf drc0
        mov r6, #0x00000001
        stad [r1,+#2], r6                  ; state = busy
        idf drc0, bif
        wdf drc0
        mov r9, #0x00000001
loop:
        ima32.u r8, r8, #1, r9.neg
        xor.testtanz.chan0 !c0, p1, r8, #0
        p1 br @loop
        br @done
done:
        mov r4, #0x00000000
        mov r3, #0x00000002
        ldad.bypassl1 r5, [r1,+#3], drc0   ; the run id, echoed
        wdf drc0
        stad [r1,+#5], r5
        stad [r1,+#1], r4                  ; cmd = 0
        idf drc0, bif
        wdf drc0
        stad [r1,+#2], r3                ; state = done
        br @tail
